import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const codeOf = (node) =>
  node && node.type === "INSTANCE" ? node.executeTemplate().example : undefined;

const vertical = instance.getEnum("Orientation", {
  horizontal: undefined,
  vertical: true,
});
const day = codeOf(instance.findInstance("Day"));
const week = codeOf(instance.findInstance("Week"));
const month = codeOf(instance.findInstance("Month"));

export default {
  id: "Multi button",
  example: figma.code`<HvMultiButton${attr("vertical", vertical)}>
  ${day ?? ""}
  ${week ?? ""}
  ${month ?? ""}
</HvMultiButton>`,
  imports: ['import { HvMultiButton } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
